frame_eqs_eel:
kick = max(bass - bass_att, 0);
pulse = max(pulse * 0.86, min(kick * 0.9, 1));
q3 = pulse;
phase = phase + 0.01 + 0.03 * min(bass_att, 2);
q1 = phase;
wave_y = 0.5 + 0.12 * sin(time * 0.21);
wave_r = NOKKVI_TEXT_R;
wave_g = NOKKVI_TEXT_G;
wave_b = NOKKVI_TEXT_B;
wave_a = 0.5 + 0.5 * min(bass_att, 1);

warp:
shader_body {
 vec2 s = texsize.xy / min(texsize.x, texsize.y);
 vec2 p = (uv - 0.5);
 vec2 flow = vec2(sin(p.y * 6.0 + time * 0.35 + q1), cos(p.x * 5.0 - time * 0.27));
 vec2 src = uv - vec2(0.0, 0.0025) + flow * 0.0022 * (0.6 + clamp(mid_att, 0.0, 2.0));
 vec3 fb = texture(sampler_main, src).xyz * (0.976 - 0.01 * q3);
 fb += (GetBlur1(src) - fb) * 0.08;
 ret = max(fb - 0.002, vec3(0.0));
}

comp:
shader_body {
 vec2 s = texsize.xy / min(texsize.x, texsize.y);
 vec3 m = texture(sampler_main, uv).xyz + GetBlur2(uv) * 0.9;
 float lum = clamp(dot(m, vec3(0.299, 0.587, 0.114)) * 1.2, 0.0, 1.0);
 float hue = abs(fract(uv.x * 0.5 + uv.y * 0.25 + q1 * 0.04) * 2.0 - 1.0);
 float band_x = clamp(hue, 0.0, 1.0) * 5.0;
 vec3 band = mix(NOKKVI_RAMP0, NOKKVI_RAMP1, clamp(band_x, 0.0, 1.0));
 band = mix(band, NOKKVI_RAMP2, clamp(band_x - 1.0, 0.0, 1.0));
 band = mix(band, NOKKVI_RAMP3, clamp(band_x - 2.0, 0.0, 1.0));
 band = mix(band, NOKKVI_RAMP4, clamp(band_x - 3.0, 0.0, 1.0));
 band = mix(band, NOKKVI_RAMP5, clamp(band_x - 4.0, 0.0, 1.0));
 vec3 col = mix(NOKKVI_BG, band, smoothstep(0.0, 0.5, lum));
 col = mix(col, NOKKVI_TEXT, smoothstep(0.8, 1.0, lum) * 0.6);
 col += NOKKVI_WARM * smoothstep(0.9, 1.0, lum) * clamp(treb_att - 1.0, 0.0, 1.0) * 0.4;
 col = mix(NOKKVI_BG, col, 0.85 + 0.15 * q3);
 ret = col;
}
